cat > pelican.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pelican Riding a Bicycle</title>
<style>
  :root{
    --sky1:#bfe6f5; --sky2:#e9f6fb; --ground:#cfe3d2; --road:#5f6b72;
    --ink:#1f2a33; --frame:#e0533d; --tire:#22282e; --spoke:#8e979d;
    --feather:#f4f7f9; --feather2:#d9e4ea; --beak:#f2a03d; --pouch:#f6c67a;
  }
  *{box-sizing:border-box}
  body{
    margin:0; min-height:100vh; display:flex; align-items:center; justify-content:center;
    background:radial-gradient(120% 120% at 50% 0%, #f7fbfd 0%, #e7eef2 60%, #d8e2e8 100%);
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    color:var(--ink); padding:24px;
  }
  .card{
    width:min(920px,100%); background:#fff; border-radius:18px;
    box-shadow:0 18px 45px rgba(31,42,51,.16), 0 2px 6px rgba(31,42,51,.08);
    padding:18px 18px 12px;
  }
  h1{margin:0 0 10px; font-size:18px; letter-spacing:.02em}
  .stage{border-radius:14px; overflow:hidden; background:linear-gradient(180deg,var(--sky1),var(--sky2) 72%,var(--ground) 72%)}
  svg{display:block; width:100%; height:auto}
  .bar{display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin:12px 2px 4px; font-size:13px}
  .bar button{
    border:1px solid #c9d4db; background:#f3f7f9; border-radius:9px; padding:7px 12px;
    font:inherit; cursor:pointer; color:var(--ink)
  }
  .bar button:hover{background:#e8f0f4}
  .bar span{color:#5b6871}
  .note{margin:6px 2px 0; font-size:12px; color:#6b7882}

  /* ---- animation ---- */
  .wheel{transform-box:fill-box; transform-origin:center; animation:spin 1.1s linear infinite}
  .crank{transform-box:fill-box; transform-origin:center; animation:spin 1.6s linear infinite}
  .leg-front{transform-box:fill-box; transform-origin:top left; animation:pedalF 1.6s linear infinite}
  .leg-back{transform-box:fill-box; transform-origin:top left; animation:pedalB 1.6s linear infinite}
  .pelican{transform-box:fill-box; transform-origin:center; animation:bob 1.6s ease-in-out infinite}
  .head{transform-box:fill-box; transform-origin:20% 80%; animation:nod 1.6s ease-in-out infinite}
  .pouch{transform-box:fill-box; transform-origin:50% 20%; animation:pouch 1.6s ease-in-out infinite}
  .wing{transform-box:fill-box; transform-origin:35% 25%; animation:flap 1.6s ease-in-out infinite}
  .road{animation:road 1.1s linear infinite}
  .dash{animation:dash 1.1s linear infinite}
  .cloud{animation:drift 14s linear infinite}
  .cloud.b{animation-duration:19s; animation-delay:-6s}
  .cloud.c{animation-duration:24s; animation-delay:-12s}
  .sun{transform-box:fill-box; transform-origin:center; animation:pulse 6s ease-in-out infinite}
  .speed{animation:speed .9s linear infinite}
  .speed.b{animation-delay:.35s}
  .speed.c{animation-delay:.7s}

  @keyframes spin{to{transform:rotate(360deg)}}
  @keyframes bob{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-4px) rotate(-1.2deg)}}
  @keyframes nod{0%,100%{transform:translate(0,0) rotate(0deg)}50%{transform:translate(1px,-2px) rotate(2deg)}}
  @keyframes pouch{0%,100%{transform:scaleY(1)}45%{transform:scaleY(1.12) translateY(1px)}}
  @keyframes flap{0%,100%{transform:rotate(0deg)}50%{transform:rotate(-7deg)}}
  @keyframes pedalF{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}
  @keyframes pedalB{0%{transform:rotate(180deg)}100%{transform:rotate(540deg)}}
  @keyframes road{to{transform:translateX(-120px)}}
  @keyframes dash{to{transform:translateX(-160px)}}
  @keyframes drift{from{transform:translateX(0)}to{transform:translateX(-160px)}}
  @keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
  @keyframes speed{0%{opacity:0; transform:translateX(20px)}20%{opacity:.75}100%{opacity:0; transform:translateX(-70px)}}

  .paused *{animation-play-state:paused !important}
  @media (prefers-reduced-motion:reduce){
    .wheel,.crank,.leg-front,.leg-back,.pelican,.head,.pouch,.wing,.road,.dash,.cloud,.sun,.speed{animation:none}
  }
</style>
</head>
<body>
<main class="card">
  <h1>Pelican riding a bicycle</h1>
  <div class="stage">
HTML
echo "part1 done"; wc -c pelican.html

